function header(){return `<div class="announcement"><span>Nationwide delivery, thoughtfully packed</span><span>Retail · wholesale · Lagos, Nigeria</span></div><header class="header" id="site-header"><button class="icon-button mobile-menu" aria-label="Open navigation" aria-expanded="false" onclick="toggleMobileMenu()">${icon('menu')}</button><div class="brand" onclick="go('home')">FASTRACK<span>FABRICS · LAGOS</span></div><nav class="nav" id="primary-nav" aria-label="Main navigation"><button onclick="go('home')">Home</button><button onclick="go('shop')">Shop fabrics</button><button onclick="go('shop','Atiku Fabrics')">Atiku</button><button onclick="go('shop','Guinea Brocade')">Brocade</button><button onclick="go('wholesale')">Wholesale</button><button onclick="go('about')">Our story</button><button class="mobile-account-link" onclick="goAccount('overview')">${customerSession?`My account`:'Sign in'}</button></nav><div class="tools"><button class="icon-button" aria-label="Search fabrics" onclick="go('shop')">${icon('search')}</button><button class="icon-button account" aria-label="Account" onclick="goAccount('overview')">${icon('user')}</button><button class="icon-button" aria-label="Wishlist" onclick="go('wishlist')">${icon('heart')}<span class="count">${wishlist.length}</span></button><button class="icon-button" aria-label="Shopping bag" onclick="cartOpen()">${icon('bag')}<span class="count">${cart.reduce((a,x)=>a+x.qty,0)}</span></button></div></header>`}
function card(p){return `<article class="product"><div class="product-image"><img class="product-img" loading="lazy" src="${imageSrc(p.img)}" alt="${esc(p.name)} fabric"><span class="tag">${(p.availableStock??p.stock)<=p.lowStock?'Low stock':'New season'}</span><button class="heart ${wishlist.includes(p.id)?'active':''}" aria-label="Save ${esc(p.name)}" onclick="toggleWish(${p.id})">${icon('heart',15)}</button></div><div class="product-meta"><p class="product-name">${esc(p.name)}</p><span class="product-desc">${esc(p.type)} · ${esc(p.color)}</span><div class="price-row"><span class="price">${money(p.price)}</span><span class="unit">${esc(p.unit)}</span></div><button class="add" ${(p.availableStock??p.stock)<=0?'disabled':''} onclick="addCart(${p.id})">${(p.availableStock??p.stock)<=0?'Out of stock':'Add to bag'}</button></div></article>`}
function productGrid(items=products){return `<div class="products">${items.map(card).join('')}</div>`}
function home(){return `${header()}<main class="home-page"><section class="hero">${heroGalleryMarkup()}<div class="hero-content"><span class="eyebrow">The new fabric edit · Lagos, Nigeria</span><h1>FABRICS<br>WITH PRESENCE.</h1><p>Discover considered Atiku, Guinea Brocade and distinctive African textiles, selected for quality, character and the way they make you feel.</p><div class="actions"><button class="button gold" onclick="go('shop')">Explore the collection</button><button class="button light" onclick="go('about')">Our story</button></div></div><div class="hero-wordmark" aria-hidden="true">FASTRACK</div><div class="hero-bottomline"><span>01 — PREMIUM AFRICAN TEXTILES</span><span>SELECTED IN LAGOS · MADE FOR YOUR NEXT</span></div>${heroGalleryControlsMarkup()}</section><section class="manifesto" data-reveal><span class="eyebrow">Quality fabrics. Distinctive style.</span><h2>Good fabric changes<br>the whole feeling.</h2><p>Thoughtfully selected textiles for the people who make, gather and celebrate.</p><button class="button outline" onclick="go('shop')">Discover Fastrack ${icon('arrow',15)}</button></section><section class="section category-section" data-reveal><div class="section-head"><div><span class="eyebrow">A study in texture</span><h2>Find your fabric.</h2></div><div class="category-nav"><button class="round-arrow" type="button" aria-label="Scroll categories left" onclick="scrollCategories(-1)">${heroControlIcon('previous')}</button><button class="round-arrow" type="button" aria-label="Scroll categories right" onclick="scrollCategories(1)">${heroControlIcon('next')}</button></div></div><div class="category-grid" id="category-strip">${categories.map(([n,img])=>`<button class="category" onclick="go('shop','${n}')"><img loading="lazy" src="${imageSrc(siteContent.textureImages[n]||img,900)}" alt="${n}"><span class="category-index">0${categories.findIndex(([name])=>name===n)+1}</span><span class="category-label">${n}</span><span class="category-arrow">${icon('arrow',17)}</span></button>`).join('')}</div><div class="category-caption"><span>ATIKU · BROCADE · JACQUARD · BAZIN</span><button class="text-button" onclick="go('shop')">Explore every fabric ${icon('arrow',15)}</button></div></section><section class="section shop-section" data-reveal><div class="section-head"><div><span class="eyebrow">The Fastrack selection</span><h2>Pieces worth keeping.</h2></div><button class="text-button" onclick="go('shop')">Shop all fabrics ${icon('arrow',15)}</button></div>${productGrid(products.slice(0,4))}</section><section class="editorial" data-reveal><img loading="lazy" src="${imageSrc(siteContent.editorialImage,1400)}" alt="FASTRACK FABRICS editorial image"><div class="editorial-copy"><span class="eyebrow">Rooted in craft</span><h2>Made for the moments that matter.</h2><p>From the first fitting to the final celebration, our fabrics bring depth, colour and considered quality to the things you make.</p><div class="actions"><button class="button gold" onclick="go('shop','Guinea Brocade')">Explore the edit ${icon('arrow',15)}</button></div><span class="editorial-index">FASTRACK FABRICS · EST. LAGOS</span></div></section><section class="section" data-reveal><div class="feature-row"><div class="feature">${icon('box',23)}<h3>Thoughtfully sourced</h3><p>Chosen for lasting quality and character.</p></div><div class="feature">${icon('truck',23)}<h3>Delivery across Nigeria</h3><p>Carefully packed and sent nationwide.</p></div><div class="feature">${icon('users',23)}<h3>Retail & wholesale</h3><p>Fabric for one project or your next collection.</p></div></div></section><section class="newsletter" data-reveal><span class="eyebrow">The Fastrack letter</span><h2>Stay ahead of the fabric edit.</h2><p>New collections, fabric stories and considered inspiration, delivered occasionally.</p><form onsubmit="subscribe(event)"><input type="email" required placeholder="Your email address" aria-label="Your email address"><button class="button">Sign me up</button></form></section></main>${footer()}`}
function heroSlides(){const uploaded=products.filter(p=>String(p.img||'').startsWith('/uploads/')).map(p=>p.img),sources=[siteContent.heroImage,...uploaded,...products.map(p=>p.img),siteContent.editorialImage,...categories.map(([name,image])=>siteContent.textureImages[name]||image)];return [...new Set(sources.filter(Boolean))].slice(0,6)}
function heroControlIcon(name){const paths={previous:'<path d="m15 18-6-6 6-6"/>',next:'<path d="m9 18 6-6-6-6"/>',pause:'<path d="M8 5h3v14H8zM15 5h3v14h-3z"/>',play:'<path d="m8 5 11 7-11 7z"/>'};return `<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`}
function heroGalleryMarkup(){return `<div class="hero-slides" aria-hidden="true">${heroSlides().map((src,index)=>`<img class="hero-slide ${index===0?'active':''}" src="${imageSrc(src,2200)}" alt="" ${index===0?'fetchpriority="high" loading="eager"':index===1?'loading="eager"':'loading="lazy"'}>`).join('')}</div>`}
function heroGalleryControlsMarkup(){const slides=heroSlides();if(slides.length<2)return '';const motion=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;return `<div class="hero-controls" role="group" aria-label="Featured fabric slideshow"><button class="hero-arrow" type="button" aria-label="Previous image" onclick="changeHeroSlide(-1)">${heroControlIcon('previous')}</button><div class="hero-dots" role="group" aria-label="Choose a slide">${slides.map((_,index)=>`<button class="hero-dot" type="button" aria-label="Show image ${index+1}" aria-pressed="${index===0}" onclick="selectHeroSlide(${index})"></button>`).join('')}</div><button class="hero-arrow" type="button" aria-label="Next image" onclick="changeHeroSlide(1)">${heroControlIcon('next')}</button>${motion?`<button class="hero-toggle" type="button" aria-label="${heroPaused?'Play':'Pause'} slideshow" aria-pressed="${heroPaused}" onclick="toggleHeroSlideshow()">${heroControlIcon(heroPaused?'play':'pause')}</button>`:''}</div>`}
function showHeroSlide(index){const slides=[...document.querySelectorAll('.hero-slide')];if(!slides.length)return;heroSlideIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('active',i===heroSlideIndex));document.querySelectorAll('.hero-dot').forEach((dot,i)=>dot.setAttribute('aria-pressed',String(i===heroSlideIndex)))}
function restartHeroSlideshow(){clearInterval(heroSlideTimer);heroSlideTimer=null;if(!document.querySelector('.hero-slides')||heroPaused||window.matchMedia('(prefers-reduced-motion: reduce)').matches||heroSlides().length<2)return;heroSlideTimer=setInterval(()=>showHeroSlide(heroSlideIndex+1),5500)}
function selectHeroSlide(index){showHeroSlide(index);restartHeroSlideshow()}
function changeHeroSlide(amount){showHeroSlide(heroSlideIndex+amount);restartHeroSlideshow()}
function toggleMobileMenu(){const header=document.querySelector('#site-header'),button=header?.querySelector('.mobile-menu');if(!header||!button)return;const open=header.classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation':'Open navigation');button.innerHTML=icon(open?'close':'menu')}
function scrollCategories(direction){const strip=document.querySelector('#category-strip');if(strip)strip.scrollBy({left:direction*strip.clientWidth*.78,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function observePageReveals(){if(revealObserver)revealObserver.disconnect();const elements=[...app.querySelectorAll('[data-reveal],.product,.category')];if(!('IntersectionObserver'in window)){elements.forEach(element=>element.classList.add('is-visible'));return}revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{rootMargin:'0px 0px -5% 0px',threshold:.08});elements.forEach((element,index)=>{element.classList.add('reveal-item');element.style.setProperty('--reveal-delay',`${index%4*70}ms`);revealObserver.observe(element)})}
function finishPageLoader(){const loader=document.querySelector('#site-loader');if(!loader||loader.dataset.finishing)return;loader.dataset.finishing='true';const wait=Math.max(0,520-(performance.now()-loaderStartedAt));setTimeout(()=>{loader.classList.add('is-complete');const progress=document.querySelector('#loader-progress');if(progress)progress.textContent='100%';setTimeout(()=>loader.remove(),650)},wait)}
function updateScrollProgress(){const root=document.documentElement,scrollable=root.scrollHeight-innerHeight,progress=scrollable>0?Math.min(100,Math.max(0,scrollY/scrollable*100)):0;const bar=document.querySelector('.reading-progress span');if(bar)bar.style.transform=`scaleX(${progress/100})`;document.querySelector('#site-header')?.classList.toggle('is-scrolled',scrollY>16)}
function toggleHeroSlideshow(){heroPaused=!heroPaused;const button=document.querySelector('.hero-toggle');if(button){button.innerHTML=heroControlIcon(heroPaused?'play':'pause');button.setAttribute('aria-label',heroPaused?'Play slideshow':'Pause slideshow');button.setAttribute('aria-pressed',String(heroPaused))}restartHeroSlideshow()}function footer(){return `<footer class="footer"><div class="footer-grid"><div><div class="brand">FASTRACK FABRICS<span>QUALITY · STYLE · HERITAGE</span></div><p>Premium African textiles, thoughtfully selected for the way you create and celebrate.</p></div><div><h4>Shop</h4><a href="#" onclick="go('shop');return false">All fabrics</a><a href="#" onclick="go('shop','Atiku Fabrics');return false">Atiku</a><a href="#" onclick="go('shop','Guinea Brocade');return false">Guinea Brocade</a><a href="#" onclick="go('shop','Bazin');return false">Bazin & lace</a></div><div><h4>Customer care</h4><a href="#" onclick="goAccount('overview');return false">My account</a><a href="#" onclick="go('track-order');return false">Track an order</a><a href="#" onclick="go('about');return false">Our story</a></div><div><h4>For business</h4><a href="#" onclick="go('wholesale');return false">Wholesale application</a><a href="#" onclick="go('request-quote');return false">Request a quote</a><a href="#" onclick="go('request-sample');return false">Request a sample</a></div></div><div class="foot-bottom">© 2026 FASTRACK FABRICS · Lagos, Nigeria</div></footer>`}
function shop(){let items=products.filter(p=>(categoryFilter==='All fabrics'||p.category===categoryFilter)&&(!query||`${p.name} ${p.category} ${p.sku} ${p.color}`.toLowerCase().includes(query.toLowerCase())));if(sort==='Price: Low to High')items.sort((a,b)=>a.price-b.price);if(sort==='Price: High to Low')items.sort((a,b)=>b.price-a.price);return `${header()}<main class="section"><span class="eyebrow">The collection</span><h2 style="font:42px var(--serif);margin:12px 0">Fabrics, considered.</h2><p class="subtle">A considered selection for the things you make and the moments you mark.</p><div class="shop-toolbar"><input placeholder="Search fabrics, colour or SKU" value="${query}" oninput="searchProducts(this.value)" aria-label="Search fabrics"><select onchange="filterCategory(this.value)"><option>All fabrics</option>${[...new Set(products.map(x=>x.category))].map(c=>`<option ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select><select onchange="sortProducts(this.value)"><option>Featured</option><option ${sort==='Price: Low to High'?'selected':''}>Price: Low to High</option><option ${sort==='Price: High to Low'?'selected':''}>Price: High to Low</option></select></div><div id="shop-results">${items.length?productGrid(items):'<p class="subtle">No fabrics match that search. Try another name, colour or product code.</p>'}</div></main>${footer()}`}
function about(){return `${header()}<main><section class="editorial"><img src="${photo('photo-1503342217505-b0a15ec3261c',1000)}" alt="African inspired fashion"><div class="editorial-copy"><span class="eyebrow">Our story · Lagos, Nigeria</span><h2>A fabric store with an eye for what comes next.</h2><p>Fastrack Fabrics brings together distinctive textiles and the people who bring them to life. We believe that what you make begins with how you choose.</p><button class="button gold" onclick="go('shop')">Discover our fabrics</button></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Quality · Authenticity · Style</span><h2>Good fabric changes everything.</h2></div></div><p class="subtle" style="max-width:650px;line-height:2">From everyday essentials to the fabric for a moment worth remembering, we curate Atiku, Guinea Brocade, Jacquard Voile and more for makers across Nigeria. Visit us online or get in touch about retail, wholesale, samples and larger orders.</p></section></main>${footer()}`}
function wishlistPage(){return `${header()}<main class="section"><span class="eyebrow">Your selection</span><h2 style="font:40px var(--serif)">Saved fabrics.</h2>${wishlist.length?productGrid(products.filter(p=>wishlist.includes(p.id))):'<p class="subtle">Your saved fabrics will be here when you find something you love.</p>'}</main>${footer()}`}
function accountAuthPage(){const signup=accountMode==='signup',forgot=accountMode==='forgot',reset=accountMode==='reset',verify=accountMode==='verify',message=accountActionMessage?`<p class="account-success" role="status">${esc(accountActionMessage)}</p>${accountActionLink?`<a class="account-action-link" href="${esc(accountActionLink)}">Open local action link ${icon('arrow',14)}</a>`:''}`:'';let form='';if(forgot){form=`<form class="account-auth-card" onsubmit="requestPasswordReset(event)"><span class="eyebrow">Account recovery</span><h2>Reset your password.</h2><p class="subtle">Enter the email address on your account. If it exists, we’ll send a reset link.</p>${message}${accountAuthError?`<p class="account-alert" role="alert">${esc(accountAuthError)}</p>`:''}<label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><button class="button account-submit" type="submit">Send reset link</button><button class="text-button" type="button" onclick="setAccountMode('signin')">Back to sign in</button></form>`}else if(reset){form=accountActionToken?`<form class="account-auth-card" onsubmit="resetCustomerPassword(event)"><span class="eyebrow">Account recovery</span><h2>Choose a new password.</h2><p class="subtle">Use at least 12 characters. This link expires after 30 minutes.</p>${accountAuthError?`<p class="account-alert" role="alert">${esc(accountAuthError)}</p>`:''}<label>New password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><label>Confirm new password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><button class="button account-submit" type="submit">Reset password</button></form>`:`<div class="account-auth-card"><span class="eyebrow">Account recovery</span><h2>That link can’t be used.</h2><p class="subtle">Request a fresh password reset link to continue.</p><button class="button account-submit" onclick="setAccountMode('forgot')">Request a new link</button></div>`}else if(verify){form=accountActionToken?`<form class="account-auth-card" onsubmit="verifyCustomerEmail(event)"><span class="eyebrow">Email verification</span><h2>Verify your email.</h2><p class="subtle">Confirm this address to link future order requests to your account. This link expires after 60 minutes.</p>${accountAuthError?`<p class="account-alert" role="alert">${esc(accountAuthError)}</p>`:''}<button class="button account-submit" type="submit">Verify email address</button></form>`:`<div class="account-auth-card"><span class="eyebrow">Email verification</span><h2>Verification link unavailable.</h2><p class="subtle">Sign in and request a fresh verification link from your account.</p><button class="button account-submit" onclick="setAccountMode('signin')">Go to sign in</button></div>`}else{form=`<form class="account-auth-card" onsubmit="submitCustomerAuth(event)"><span class="eyebrow">${signup?'Create an account':'Welcome back'}</span><h2>${signup?'Join FASTRACK.':'Sign in.'}</h2><p class="subtle">${signup?'Save fabrics and follow your order requests from your own account.':'Continue to your personal FASTRACK account.'}</p>${message}${accountAuthError?`<p class="account-alert" role="alert">${esc(accountAuthError)}</p>`:''}${signup?`<label>Full name<input name="fullName" autocomplete="name" maxlength="160" required></label><label>Phone number <span class="subtle">optional</span><input name="phone" type="tel" autocomplete="tel" placeholder="+234 801 234 5678"></label>`:''}<label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?'12':'1'}" maxlength="1024" required>${signup?'<small>Use at least 12 characters.</small>':''}</label><button class="button account-submit" type="submit">${signup?'Create my account':'Sign in'}</button>${!signup?'<button type="button" class="account-forgot" onclick="setAccountMode(\'forgot\')">Forgot your password?</button>':''}<p class="account-switch">${signup?'Already have an account?':'New to FASTRACK?'} <button type="button" onclick="setAccountMode('${signup?'signin':'signup'}')">${signup?'Sign in':'Create an account'}</button></p><p class="account-guest-note">You can also continue shopping and submit an order request as a guest.</p><button class="text-button" type="button" onclick="go('shop')">Return to the fabric collection ${icon('arrow',14)}</button></form>`}return `${header()}<main class="account-auth-page"><section class="account-auth-image"><span class="eyebrow">Your FASTRACK account</span><h1>A more personal way to shop.</h1><p>Keep your fabric selection, order requests and details together in one place.</p><span class="account-auth-signature">FASTRACK FABRICS · LAGOS</span></section><section class="account-auth-panel">${form}</section></main>${footer()}`}
function accountPage(){if(!customerSession)return accountAuthPage();const customer=customerSession.customer,tab=accountTab;const tabs=[['overview','Overview','/account'],['orders','Order requests','/account/orders'],['saved','Saved fabrics','/account/saved'],['profile','Profile','/account/profile']];let content='';if(tab==='overview'){content=`<section class="account-welcome"><span class="eyebrow">Your account</span><h1>Welcome, ${esc(customer.fullName.split(' ')[0])}.</h1><p class="subtle">Your order requests and saved fabrics, together in one place.</p></section><div class="account-stat-grid"><article><span>Order requests</span><strong>${accountOrders?accountOrders.length:'—'}</strong><button onclick="goAccount('orders')">View history ${icon('arrow',14)}</button></article><article><span>Saved fabrics</span><strong>${wishlist.length}</strong><button onclick="goAccount('saved')">View your selection ${icon('arrow',14)}</button></article></div><section class="account-section"><div class="account-section-head"><div><span class="eyebrow">Your activity</span><h2>Recent order requests</h2></div><button class="text-button" onclick="goAccount('orders')">See all ${icon('arrow',14)}</button></div>${accountOrders===null?(accountOrdersLoading?'<p class="subtle">Loading your order history…</p>':`<p class="subtle">${esc(accountOrdersError)}</p>`):accountOrders.length?accountOrders.slice(0,3).map(customerOrderCard).join(''):'<div class="account-empty"><h3>Your order history starts here.</h3><p class="subtle">Order requests submitted while signed in will appear here.</p><button class="button outline" onclick="go(\'shop\')">Explore fabrics</button></div>'}</section>`}else if(tab==='orders'){content=`<div class="account-section-head"><div><span class="eyebrow">Your activity</span><h1>Order requests</h1></div><button class="text-button" onclick="refreshCustomerOrders()">Refresh ${icon('arrow',14)}</button></div><p class="subtle account-helper">Requests submitted while signed in appear here. Guest requests can still be followed from Track an order.</p>${accountOrders===null?(accountOrdersLoading?'<p class="subtle">Loading your order history…</p>':`<p class="account-alert">${esc(accountOrdersError)}</p>`):accountOrders.length?accountOrders.map(customerOrderCard).join(''):'<div class="account-empty"><h3>No order requests yet.</h3><p class="subtle">When you place an order request while signed in, you can follow its progress here.</p><button class="button outline" onclick="go(\'shop\')">Browse fabrics</button></div>'}`}else if(tab==='saved'){const savedProducts=products.filter(product=>wishlist.includes(product.id));content=`<div class="account-section-head"><div><span class="eyebrow">Your selection</span><h1>Saved fabrics</h1></div><button class="text-button" onclick="go(\'shop\')">Browse fabrics ${icon('arrow',14)}</button></div>${savedProducts.length?productGrid(savedProducts):'<div class="account-empty"><h3>Your saved fabrics will appear here.</h3><p class="subtle">Tap the heart on any fabric to keep it in your personal selection.</p><button class="button outline" onclick="go(\'shop\')">Explore the collection</button></div>'}`}else{content=`<section class="account-section"><span class="eyebrow">Personal details</span><h1>Your profile</h1><p class="subtle account-helper">Keep your contact details current for order updates.</p>${accountNotice?`<p class="account-success" role="status">${esc(accountNotice)}</p>`:''}<form class="account-profile-form" onsubmit="saveCustomerProfile(event)"><label>Full name<input name="fullName" autocomplete="name" maxlength="160" value="${esc(customer.fullName)}" required></label><label>Email address<input value="${esc(customer.email)}" readonly aria-describedby="account-email-note"><small id="account-email-note">Your sign-in email cannot be changed here.</small></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" maxlength="30" value="${esc(customer.phone||'')}" placeholder="+234 801 234 5678"></label><button class="button" type="submit">Save profile</button></form><div class="account-member-note">Account created ${esc(String(customer.createdAt||'').slice(0,10)||'recently')}</div></section>`}if((tab==='overview'||tab==='orders')&&accountOrders===null&&!accountOrdersLoading)loadCustomerOrders();return `${header()}<main class="account-page"><aside class="account-side"><div class="account-customer"><span class="account-avatar">${icon('user',19)}</span><div><strong>${esc(customer.fullName)}</strong><span>${esc(customer.email)}</span></div></div><nav aria-label="Account navigation">${tabs.map(([id,label,path])=>`<button class="account-nav-item ${tab===id?'active':''}" onclick="goAccount('${id}')">${icon(id==='overview'?'chart':id==='orders'?'bag':id==='saved'?'heart':'user',17)}<span>${label}</span></button>`).join('')}</nav><button class="account-logout" onclick="customerLogout()">Sign out</button></aside><section class="account-main">${content}</section></main>${footer()}`}
function customerOrderCard(order){const status=String(order.status||'pending').replace(/-/g,' '),items=(order.items||[]).map(item=>`${esc(item.productName)} · ${Number(item.quantity).toLocaleString()} ${esc(item.unit)}`).join(' / ');return `<article class="customer-order-card"><div class="customer-order-head"><div><span class="eyebrow">${esc(order.orderNumber)}</span><p>${esc(String(order.createdAt||'').slice(0,16))}</p></div><span class="customer-order-status status-${esc(order.status||'pending')}">${esc(status)}</span></div><p class="customer-order-items">${items||'Fabric order request'}</p><div class="customer-order-total"><span>Subtotal</span><strong>${money(order.subtotal)}</strong></div><p class="subtle customer-order-note">${order.paymentStatus==='not_configured'?'Payment to be arranged with FASTRACK.':`Payment status: ${esc(order.paymentStatus||'pending')}.`} ${order.deliveryMethod==='pickup'?'Store pickup':`Delivery: ${esc([order.city,order.state].filter(Boolean).join(', ')||'to be confirmed')}`}</p></article>`}
function accountVerificationMarkup(customer){return `<div class="account-verify-banner"><div><strong>Email address not verified</strong><p>Verify ${esc(customer.email)} before linking new order requests to your account.</p></div><button class="button outline" onclick="resendCustomerVerification()">Send verification email</button>${accountActionMessage?`<p class="account-verify-message" role="status">${esc(accountActionMessage)}</p>`:''}${accountActionLink?`<a class="account-action-link" href="${esc(accountActionLink)}">Open local verification link ${icon('arrow',14)}</a>`:''}</div>`}
function prefillCustomerCheckout(){const form=app.querySelector('.checkout-form');if(!form||!customerSession)return;const customer=customerSession.customer;for(const [name,value] of Object.entries({fullName:customer.fullName,phone:customer.phone,email:customer.email})){const field=form.elements[name];if(field&&!field.value)field.value=value||''}const note=document.createElement('p');note.className='account-checkout-note';note.textContent=customer.emailVerifiedAt?'You are signed in and verified. This order request will be saved to your account.':'Verify your email to link this request to your account; you can still submit this as a guest.';form.prepend(note)}
function goAccount(tab='overview'){accountTab=tab;accountAuthError='';accountNotice='';page='account';const path=tab==='orders'?'/account/orders':tab==='profile'?'/account/profile':tab==='saved'?'/account/saved':'/account';history.pushState(null,'',path);render();scrollTo(0,0)}
function setAccountMode(mode){accountMode=mode;accountAuthError='';accountActionToken='';if(mode==='forgot'){accountActionMessage='';accountActionLink=''}page='account';const path=mode==='signup'?'/account/signup':mode==='forgot'?'/account/forgot':'/account';history.pushState(null,'',path);render();scrollTo(0,0)}
async function refreshCustomerSession(){try{const response=await fetch('/api/customer/session',{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error('Account session unavailable.');if(data.authenticated){customerSession=data;const merged=[...new Set([...(data.wishlist||[]).map(Number),...guestWishlist.map(Number)])];const needsSync=merged.length!==(data.wishlist||[]).length||merged.some(id=>!(data.wishlist||[]).includes(id));wishlist=merged;save();if(needsSync)syncCustomerWishlist();if(location.pathname==='/account/signup')history.replaceState(null,'','/account');}else customerSession=null;if(page==='account')render()}catch{customerSession=null;if(page==='account')render()}}
async function applyCustomerSession(data){customerSession={authenticated:true,customer:data.customer,wishlist:data.wishlist||[]};const remote=(data.wishlist||[]).map(Number),merged=[...new Set([...remote,...guestWishlist.map(Number)])],needsSync=merged.length!==remote.length||merged.some(id=>!remote.includes(id));wishlist=merged;save();if(needsSync)await syncCustomerWishlist();accountOrders=null;accountOrdersError='';}
async function syncCustomerWishlist(){if(!customerSession)return;try{const response=await fetch('/api/customer/wishlist',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({productIds:wishlist})});if(response.ok){const data=await response.json();wishlist=data.productIds||wishlist;save()}}catch{}}
async function submitCustomerAuth(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form).entries()),signup=accountMode==='signup',button=form.querySelector('[type="submit"]');accountAuthError='';button.disabled=true;button.textContent=signup?'Creating account…':'Signing in…';try{const response=await fetch(signup?'/api/customer/register':'/api/customer/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error||'We could not complete sign in.');if(signup){accountActionLink=result.developmentActionUrl||'';accountActionMessage=accountActionLink?'Your account is ready. Use the local link below to verify your email.':'We sent a verification email. Check your inbox.'}else{accountActionLink='';accountActionMessage=''}await applyCustomerSession(result);accountMode='signin';accountTab='overview';page='account';history.pushState(null,'','/account');render();scrollTo(0,0)}catch(error){accountAuthError=error.message;render()}finally{const current=app.querySelector('.account-submit');if(current)current.disabled=false}}
async function resendCustomerVerification(){accountActionMessage='';accountActionLink='';try{const response=await fetch('/api/customer/send-verification',{method:'POST'}),result=await response.json();if(!response.ok)throw new Error(result.error||'We could not send the verification email.');if(result.alreadyVerified){await refreshCustomerSession();showToast('Your email is already verified.');return}accountActionLink=result.developmentActionUrl||'';accountActionMessage=accountActionLink?'Local verification link is ready below.':'Verification email sent. Check your inbox.';await refreshCustomerSession();render()}catch(error){showToast(error.message)}}
async function requestPasswordReset(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),email=form.elements.email.value;accountAuthError='';accountActionMessage='';accountActionLink='';button.disabled=true;button.textContent='Sending…';try{const response=await fetch('/api/customer/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})}),result=await response.json();if(!response.ok)throw new Error(result.error||'We could not request a reset link.');accountActionMessage='If an account exists for that email, a password reset link has been sent.';accountActionLink=result.developmentActionUrl||'';render()}catch(error){accountAuthError=error.message;render()}finally{const current=app.querySelector('.account-auth-card [type="submit"]');if(current)current.disabled=false}}
async function verifyCustomerEmail(event){event.preventDefault();const button=event.currentTarget.querySelector('[type="submit"]');accountAuthError='';button.disabled=true;button.textContent='Verifying…';try{const response=await fetch('/api/customer/verify-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:accountActionToken})}),result=await response.json();if(!response.ok)throw new Error(result.error||'This verification link is invalid or expired.');accountActionToken='';accountActionLink='';accountActionMessage='Your email address is verified.';if(customerSession){await refreshCustomerSession();if(customerSession){accountMode='signin';accountTab='overview';history.replaceState(null,'','/account');render();showToast('Your email address is verified.');return}}accountMode='signin';page='account';history.replaceState(null,'','/account');render()}catch(error){accountAuthError=error.message;render()}finally{const current=app.querySelector('.account-submit');if(current)current.disabled=false}}
async function resetCustomerPassword(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form).entries()),button=form.querySelector('[type="submit"]');accountAuthError='';if(data.password!==data.confirmPassword){accountAuthError='The passwords do not match.';render();return}button.disabled=true;button.textContent='Resetting…';try{const response=await fetch('/api/customer/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:accountActionToken,password:data.password})}),result=await response.json();if(!response.ok)throw new Error(result.error||'We could not reset your password.');customerSession=null;accountOrders=null;accountActionToken='';accountActionLink='';accountMode='signin';accountActionMessage='Your password has been reset. Sign in with your new password.';page='account';history.pushState(null,'','/account');render()}catch(error){accountAuthError=error.message;render()}finally{const current=app.querySelector('.account-submit');if(current)current.disabled=false}}
async function saveCustomerProfile(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]');accountNotice='';button.disabled=true;try{const data=Object.fromEntries(new FormData(form).entries()),response=await fetch('/api/customer/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Profile could not be saved.');customerSession={authenticated:true,customer:result.customer,wishlist:result.wishlist||wishlist};accountNotice='Your profile has been updated.';render()}catch(error){accountNotice='';showToast(error.message);render()}finally{const current=app.querySelector('.account-profile-form [type="submit"]');if(current)current.disabled=false}}
async function loadCustomerOrders(){if(!customerSession||accountOrdersLoading)return;accountOrdersLoading=true;accountOrdersError='';try{const response=await fetch('/api/customer/orders',{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Your order history is unavailable.');accountOrders=data}catch(error){accountOrdersError=error.message}finally{accountOrdersLoading=false;if(page==='account')render()}}
function refreshCustomerOrders(){accountOrders=null;loadCustomerOrders()}
async function customerLogout(){try{await fetch('/api/customer/logout',{method:'POST'})}catch{}customerSession=null;accountOrders=null;accountMode='signin';wishlist=[...guestWishlist];save();goAccount('overview')}
let trackResult=null,trackError='';
function trackOrderPage(){const result=trackResult,statusNames={pending:'Order request received',pending_payment:'Awaiting payment',payment_failed:'Payment failed',payment_review:'Payment review',confirmed:'Order confirmed',processing:'Being prepared',packed:'Packed',dispatched:'Dispatched',delivered:'Delivered',cancelled:'Cancelled'};return `${header()}<main class="section track-page"><span class="eyebrow">Order support</span><h1>Track your order.</h1><p class="subtle">Enter your order reference and the phone number or email used when you placed the request.</p><form class="track-form" onsubmit="submitTrackOrder(event)"><label>Order reference<input name="reference" placeholder="FF-2026-ABC123" maxlength="20" required></label><label>Phone number or email<input name="contact" autocomplete="email" maxlength="254" required></label><button class="button" type="submit">Find order</button></form>${trackError?`<p class="form-error track-error">${esc(trackError)}</p>`:''}${result?`<section class="track-result"><div class="track-result-head"><div><span class="eyebrow">${esc(result.orderNumber)}</span><h2>${esc(statusNames[result.status]||result.status)}</h2></div><span class="status ${result.status==='cancelled'?'low':''}">${esc(statusNames[result.status]||result.status)}</span></div><p class="subtle">Request placed ${esc(result.createdAt)} · ${result.deliveryMethod==='pickup'?'Store pickup':`${esc(result.city)}, ${esc(result.state)}`}</p><div class="track-timeline">${result.history.map(item=>`<div class="track-event"><span class="track-marker"></span><div><strong>${esc(statusNames[item.status]||item.status)}</strong><p class="subtle">${esc(item.note)}</p><small>${esc(item.createdAt)}</small></div></div>`).join('')}</div><h3>Items requested</h3>${result.items.map(item=>`<div class="track-item"><span>${esc(item.productName)}<small>${Number(item.quantity).toLocaleString()} ${esc(item.unit)} · ${esc(item.color)}</small></span><strong>${money(item.lineTotal)}</strong></div>`).join('')}<div class="track-total"><span>Subtotal</span><strong>${money(result.subtotal)}</strong></div><p class="subtle">Payment status: ${esc(result.paymentStatus==='not_configured'?'Payment to be arranged with FASTRACK':result.paymentStatus)}. Delivery charges, if applicable, are confirmed by our team.</p></section>`:''}</main>${footer()}`}
async function submitTrackOrder(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries());trackError='';trackResult=null;const params=new URLSearchParams({reference:data.reference,contact:data.contact});try{const response=await fetch(`/api/orders/track?${params}`),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not find the order.');trackResult=result}catch(error){trackError=error.message}render()}
let requestReceipt=null;
function requestForm(kind){const title=kind==='wholesale'?'Wholesale partnership':kind==='quote'?'Request a fabric quote':'Request a fabric sample',eyebrow=kind==='wholesale'?'For business':'A personal service',intro=kind==='wholesale'?'Tell us about your business. Our team will review your application and contact you about wholesale terms.':kind==='quote'?'Share the fabric, quantity and delivery details. Our team will prepare a quotation for your request.':'Choose a fabric and tell us where to send a sample request. Our team will confirm sample availability and delivery details.',endpoint=kind==='wholesale'?'/api/requests/wholesale':kind==='quote'?'/api/requests/quote':'/api/requests/sample';if(requestReceipt?.kind===kind){return `${header()}<main class="section request-page"><span class="eyebrow">Request received</span><h1>${title}</h1><p class="subtle">${kind==='quote'?`Quote reference: <strong>${esc(requestReceipt.reference)}</strong>. `:`Reference: <strong>${esc(requestReceipt.reference)}</strong>. `}The FASTRACK team will follow up using the contact details you provided.</p><button class="button" onclick="requestReceipt=null;go('shop')">Continue shopping</button></main>${footer()}`}const contact=`<label>Full name<input name="fullName" autocomplete="name" maxlength="160" required></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" placeholder="+234 801 234 5678" required></label><label class="field-wide">Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label>`;let fields='';if(kind==='wholesale')fields=`<div class="checkout-fields">${contact}<label>Business name<input name="businessName" maxlength="180" required></label><label>Business type<select name="businessType" required><option value="">Choose a business type</option><option>Fashion designer or tailor</option><option>Boutique or retailer</option><option>Clothing brand</option><option>Event planner</option><option>Fabric reseller</option><option>Other</option></select></label><label class="field-wide">Business address<input name="businessAddress" autocomplete="street-address" maxlength="500" required></label><label>State<input name="state" autocomplete="address-level1" maxlength="80" required></label><label>Estimated monthly purchase<input name="monthlyPurchase" maxlength="120" placeholder="For example, 50 yards"></label><label class="field-wide">Website or social media<input name="onlinePresence" maxlength="300" placeholder="https://"></label><label class="field-wide">Additional information<textarea name="additionalInfo" maxlength="2000" rows="4"></textarea></label></div>`;else fields=`<div class="checkout-fields">${contact}<label class="field-wide">Fabric<select name="productId" required><option value="">Choose a fabric</option>${products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.sku)}</option>`).join('')}</select></label><label>Preferred colour<input name="${kind==='quote'?'desiredColour':'preferredColour'}" maxlength="100" placeholder="If different from listed colour"></label><label>${kind==='quote'?'Quantity requested':'Number of samples'}<input name="quantity" type="number" min="${kind==='quote'?'0.01':'1'}" step="${kind==='quote'?'0.01':'1'}" max="${kind==='quote'?'100000':'1000'}" required></label><label class="field-wide">${kind==='quote'?'Delivery location':'Delivery address or pickup location'}<input name="deliveryLocation" maxlength="300" autocomplete="street-address" required></label>${kind==='quote'?'<label>Required by<input name="deadline" type="date"></label>':''}<label class="field-wide">Additional details<textarea name="message" maxlength="1500" rows="3" placeholder="Tell us about colour, project, timing or other requirements"></textarea></label></div>`;return `${header()}<main class="section request-page"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subtle request-intro">${intro}</p><form class="checkout-form request-form" data-endpoint="${endpoint}" onsubmit="submitBusinessRequest(event,'${kind}')">${fields}<p class="form-error" data-error></p><button class="button" type="submit">${kind==='wholesale'?'Submit application':kind==='quote'?'Send quote request':'Send sample request'}</button><p class="subtle">Submitting this form sends a request only. We will contact you to confirm availability, pricing and delivery.</p></form></main>${footer()}`}
async function submitBusinessRequest(event,kind){event.preventDefault();const form=event.currentTarget,error=form.querySelector('[data-error]'),button=form.querySelector('button[type="submit"]'),data=Object.fromEntries(new FormData(form).entries());error.textContent='';button.disabled=true;button.textContent='Sending…';try{const response=await fetch(form.dataset.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Your request could not be submitted.');requestReceipt={kind,reference:result.quoteNumber||`${kind==='wholesale'?'W':'S'}-${String(result.id).padStart(5,'0')}`};render();scrollTo(0,0)}catch(err){error.textContent=err.message;button.disabled=false;button.textContent=kind==='wholesale'?'Submit application':kind==='quote'?'Send quote request':'Send sample request'}}
function go(next,cat='All fabrics'){page=next;categoryFilter=cat;query='';requestReceipt=null;transitionOnRender=true;if(next!=='track-order'){trackResult=null;trackError=''}const paths={home:'/',shop:'/shop',about:'/about',wishlist:'/wishlist',cart:'/cart',checkout:'/checkout','order-confirmation':'/order-confirmation',wholesale:'/wholesale','request-quote':'/request-quote','request-sample':'/request-sample','track-order':'/track-order'};history.pushState(null,'',`${paths[next]||'/'}${next==='shop'&&cat!=='All fabrics'?`?category=${encodeURIComponent(cat)}`:''}`);paymentReturnReference='';paymentReturnStatus='idle';render();scrollTo(0,0)}function render(){clearInterval(heroSlideTimer);heroSlideTimer=null;if(page==='admin'){admin();return}const requests={wholesale:()=>requestForm('wholesale'),'request-quote':()=>requestForm('quote'),'request-sample':()=>requestForm('sample')},showAccountAuth=page==='account'&&(!customerSession||['forgot','reset','verify'].includes(accountMode));app.innerHTML=showAccountAuth?accountAuthPage():page==='account'?accountPage():page==='shop'?shop():page==='about'?about():page==='wishlist'?wishlistPage():page==='checkout'?checkout():page==='order-confirmation'?orderConfirmation():page==='track-order'?trackOrderPage():requests[page]?requests[page]():home();if(page==='account'&&customerSession&&!customerSession.customer.emailVerifiedAt){app.querySelector('.account-main')?.insertAdjacentHTML('afterbegin',accountVerificationMarkup(customerSession.customer))}if(page==='checkout'){prefillCustomerCheckout();updatePaymentCheckoutUI()}if(page==='order-confirmation'&&paymentReturnReference&&paymentReturnStatus==='idle'){paymentReturnStatus='checking';queueMicrotask(verifyPaystackReturn)}if(transitionOnRender){const main=app.querySelector('main');if(main){main.classList.add('page-enter');requestAnimationFrame(()=>main.classList.add('page-entered'))}transitionOnRender=false}observePageReveals();if(page==='home'){heroSlideIndex=0;showHeroSlide(0);restartHeroSlideshow()}updateScrollProgress()}
function save(){localStorage.setItem('ff-cart',JSON.stringify(cart));localStorage.setItem('ff-wish',JSON.stringify(wishlist));if(!customerSession)localStorage.setItem('ff-guest-wish',JSON.stringify(guestWishlist))}function addCart(id){let line=cart.find(x=>x.id===id);if(line)line.qty++;else cart.push({id,qty:1});save();showToast('Added to your bag');render()}
function toggleWish(id){wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];if(!customerSession)guestWishlist=[...wishlist];save();if(customerSession)syncCustomerWishlist();render()}
function changeQty(id,n){let x=cart.find(a=>a.id===id);x.qty+=n;if(x.qty<=0)cart=cart.filter(a=>a.id!==id);save();document.querySelector('.overlay')?.remove();openCartDrawer()}
function showToast(text){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${text}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2600)}function filterCategory(v){categoryFilter=v;render()}function sortProducts(v){sort=v;render()}function searchProducts(v){query=v;let box=document.querySelector('#shop-results');let items=products.filter(p=>(categoryFilter==='All fabrics'||p.category===categoryFilter)&&(!query||`${p.name} ${p.category} ${p.sku} ${p.color}`.toLowerCase().includes(query.toLowerCase())));box.innerHTML=items.length?productGrid(items):'<p class="subtle">No fabrics match that search.</p>'}function subscribe(e){e.preventDefault();showToast('Thank you for joining the Fastrack letter');e.target.reset()}

let adminSession={configured:false,authenticated:false,view:'Dashboard'};
let lastOrder=null;
function openCartDrawer(){const total=cart.reduce((sum,item)=>sum+Number(products.find(p=>p.id===item.id)?.price||0)*item.qty,0);const html=`<div class="overlay" onclick="if(event.target===this)render()"><aside class="drawer"><div class="drawer-head"><h3>Your bag (${cart.reduce((a,x)=>a+x.qty,0)})</h3><button class="icon-button" onclick="render()" aria-label="Close">${icon('close')}</button></div>${cart.length?cart.map(x=>{const p=products.find(y=>y.id===x.id);if(!p)return '';return `<div class="cart-line"><img src="${imageSrc(p.img,200)}" alt=""><div><h4>${esc(p.name)}</h4><p>${money(p.price)} · ${esc(p.unit)}</p><div class="qty"><button onclick="changeQty(${p.id},-1)">−</button>${x.qty}<button onclick="changeQty(${p.id},1)">+</button></div></div><b>${money(p.price*x.qty)}</b></div>`}).join(''):`<p class="subtle" style="padding:32px 0">Your bag is ready for something considered.</p>`}<div class="cart-total"><span>Subtotal</span><span>${money(total)}</span></div>${cart.length?'<button class="button" onclick="go(\'checkout\')">Continue to checkout</button>':'<button class="button" onclick="go(\'shop\')">Explore the collection</button>'}<p class="subtle" style="line-height:1.7;margin-top:17px">Delivery cost is confirmed with you before payment. ${paymentsEnabled?'Pay securely through Paystack at checkout.':'Checkout currently sends an order request only.'}</p></aside></div>`;app.insertAdjacentHTML('beforeend',html)}
function checkout(){const subtotal=cart.reduce((sum,item)=>sum+Number(products.find(p=>p.id===item.id)?.price||0)*item.qty,0);if(!cart.length)return `${header()}<main class="section"><span class="eyebrow">Your order</span><h2 style="font:40px var(--serif)">Your bag is empty.</h2><p class="subtle">Explore the fabric collection before starting an order request.</p><button class="button" onclick="go('shop')">Shop fabrics</button></main>${footer()}`;const states=[...new Set(deliveryZones.map(zone=>zone.state))],stateField=states.length?`<select name="state" autocomplete="address-level1" onchange="updateDeliveryEstimate()" required><option value="">Choose a state</option>${states.map(state=>`<option value="${esc(state)}">${esc(state)}</option>`).join('')}</select>`:`<input name="state" autocomplete="address-level1" maxlength="80" oninput="updateDeliveryEstimate()" required>`;return `${header()}<main class="section checkout-wrap"><div><span class="eyebrow">Order request</span><h1 class="checkout-title">A few details, then we’ll take it from here.</h1><p class="subtle checkout-intro">Send your fabric request. We’ll confirm stock and delivery details with you before payment.</p><form class="checkout-form" onsubmit="placeOrder(event)"><h2>Your details</h2><div class="checkout-fields"><label>Full name<input name="fullName" autocomplete="name" maxlength="160" required></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" placeholder="+234 801 234 5678" required></label><label class="field-wide">Email address <span class="subtle">optional</span><input name="email" type="email" autocomplete="email" maxlength="254"></label></div><h2>How would you like to receive it?</h2><label>Delivery method<select name="deliveryMethod" onchange="deliveryFields()"><option value="delivery">Home delivery</option><option value="pickup">Store pickup</option></select></label><div class="checkout-fields delivery-fields"><label>State${stateField}</label><label>City<input name="city" autocomplete="address-level2" maxlength="120" oninput="updateDeliveryEstimate()" required></label><label class="field-wide">Delivery address<textarea name="address" autocomplete="street-address" maxlength="500" rows="2" required></textarea></label></div><label>Delivery instructions <span class="subtle">optional</span><textarea name="instructions" maxlength="1000" rows="2"></textarea></label><div class="checkout-notice"><strong>${deliveryZones.length?'Delivery fees are calculated from the configured delivery zones.':'Payment and delivery fees are not configured yet.'}</strong><span>${deliveryZones.length?'Choose a supported area to see its delivery fee and estimated timing. Order requests stay unpaid until FASTRACK confirms the details.':'No payment will be collected. This creates a request for the FASTRACK team to confirm availability and delivery cost. Your order is not confirmed and stock is not reserved at this stage.'}</span></div><p class="form-error" data-error></p><button class="button checkout-submit">Submit order request</button></form></div><aside class="order-summary"><h2>Order summary</h2>${cart.map(x=>{const p=products.find(y=>y.id===x.id);return p?`<div class="summary-line"><span>${esc(p.name)}<small>${x.qty} × ${esc(p.unit)} · ${money(p.price)}</small></span><b>${money(p.price*x.qty)}</b></div>`:''}).join('')}<div class="summary-line"><span>Subtotal</span><b>${money(subtotal)}</b></div><div class="summary-line"><span>Delivery</span><span class="subtle" id="delivery-fee-label">${deliveryZones.length?'Choose delivery area':'To confirm'}</span></div><div class="summary-total"><span>Estimated total</span><b id="checkout-total">${money(subtotal)}</b></div><button class="text-button" onclick="openCartDrawer()">Edit your bag</button></aside></main>${footer()}`}
function updatePaymentCheckoutUI(){const form=document.querySelector('.checkout-form'),wrap=document.querySelector('.checkout-wrap');if(!form||!wrap)return;const emailLabel=form.elements.email?.closest('label'),button=form.querySelector('.checkout-submit'),title=wrap.querySelector('.checkout-title'),intro=wrap.querySelector('.checkout-intro'),notice=form.querySelector('.checkout-notice');if(paymentsEnabled){if(title)title.textContent='Complete your fabric order securely.';if(intro)intro.textContent='Your order total is calculated from the current catalog and delivery zone. Pay securely through Paystack to confirm it.';if(emailLabel){emailLabel.firstChild.textContent='Email address ';emailLabel.querySelector('.subtle')?.remove();form.elements.email.required=true}if(notice){notice.querySelector('strong').textContent='Secure online payment';notice.querySelector('span').textContent='Paystack will process your payment. Stock is reserved for 30 minutes and the order is confirmed only after the server verifies payment.'}if(button)button.textContent='Continue to secure payment'}else if(button){button.textContent='Submit order request'}}
async function refreshPaymentConfig(){try{const response=await fetch('/api/payment/config',{cache:'no-store'}),config=await response.json();if(!response.ok)return;const changed=paymentsEnabled!==Boolean(config.enabled);paymentsEnabled=Boolean(config.enabled);if(changed&&page==='checkout')render()}catch{paymentsEnabled=false}}
function deliveryFields(){const form=document.querySelector('.checkout-form');if(!form)return;const pickup=form.elements.deliveryMethod.value==='pickup';form.querySelectorAll('.delivery-fields input,.delivery-fields select,.delivery-fields textarea').forEach(el=>{el.required=!pickup});form.querySelector('.delivery-fields').hidden=pickup;updateDeliveryEstimate()}
function findDeliveryZone(state,city){const normalizedState=String(state||'').trim().toLowerCase(),normalizedCity=String(city||'').trim().toLowerCase();if(!normalizedState)return null;return deliveryZones.find(zone=>zone.state.trim().toLowerCase()===normalizedState&&zone.city&&zone.city.trim().toLowerCase()===normalizedCity)||deliveryZones.find(zone=>zone.state.trim().toLowerCase()===normalizedState&&!zone.city)||null}
function updateDeliveryEstimate(){const form=document.querySelector('.checkout-form'),label=document.querySelector('#delivery-fee-label'),totalNode=document.querySelector('#checkout-total');if(!form||!label||!totalNode)return;const subtotal=cart.reduce((sum,item)=>sum+Number(products.find(product=>product.id===item.id)?.price||0)*item.qty,0);if(form.elements.deliveryMethod.value==='pickup'){label.textContent=money(0);totalNode.textContent=money(subtotal);return}const zone=findDeliveryZone(form.elements.state?.value,form.elements.city?.value);if(!zone){label.textContent=deliveryZones.length?'Area not configured':'To confirm';totalNode.textContent=money(subtotal);return}label.textContent=`${money(zone.fee)}${zone.estimate?` · ${zone.estimate}`:''}`;totalNode.textContent=money(subtotal+Number(zone.fee))}
async function placeOrder(e){e.preventDefault();const form=e.target,error=form.querySelector('[data-error]'),data=Object.fromEntries(new FormData(form).entries());data.items=cart.map(x=>({id:x.id,quantity:x.qty}));error.textContent='';const button=form.querySelector('.checkout-submit');button.disabled=true;button.textContent=paymentsEnabled?'Starting secure payment…':'Sending request…';try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await r.json();if(!r.ok)throw new Error(result.error||'Your request could not be sent.');if(result.paymentRequired){if(!/^https:\/\/checkout\.paystack\.com\//i.test(result.authorizationUrl||''))throw new Error('The secure payment link could not be verified. Contact FASTRACK before retrying.');cart=[];save();location.assign(result.authorizationUrl);return}lastOrder=result;cart=[];save();paymentReturnReference='';paymentReturnStatus='idle';page='order-confirmation';history.pushState(null,'','/order-confirmation');render();scrollTo(0,0)}catch(err){error.textContent=err.message;button.disabled=false;button.textContent=paymentsEnabled?'Continue to secure payment':'Submit order request'}}
async function verifyPaystackReturn(){if(!paymentReturnReference)return;paymentReturnStatus='checking';paymentReturnError='';render();try{const response=await fetch('/api/payments/paystack/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference:paymentReturnReference})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Payment status could not be checked.');paymentReturnStatus=result.status;paymentReturnOrderNumber=result.orderNumber||''}catch(error){paymentReturnStatus='unavailable';paymentReturnError=error.message||'Payment status could not be checked.'}render()}
function retryPaymentCheck(){paymentReturnStatus='idle';render()}
function orderConfirmation(){if(paymentReturnReference){const title={checking:'Checking your payment',successful:'Payment confirmed',pending:'Payment is still processing',failed:'Payment was not completed',review:'Your payment needs a quick review',unavailable:'Payment status is temporarily unavailable'}[paymentReturnStatus]||'Checking your payment',message={checking:'We are confirming the transaction directly with Paystack. Please keep this page open.',successful:'Your payment has been verified and your order is confirmed. FASTRACK will prepare the fabric for fulfilment.',pending:'Paystack has not confirmed the transaction yet. Check again in a moment; do not submit the order again.',failed:'Paystack did not complete this payment. No order was confirmed. You can return to your bag and try again.',review:'Paystack reported a payment that needs staff review before fulfilment. Please contact FASTRACK with the order reference.',unavailable:paymentReturnError||'Please check again in a moment. Do not submit another payment while the status is unknown.'}[paymentReturnStatus]||'We are checking your payment.';return `${header()}<main class="section confirmation"><span class="eyebrow">${paymentReturnStatus==='successful'?'Secure payment':paymentReturnStatus==='review'?'Payment support':'Order update'}</span><h1>${esc(title)}.</h1>${paymentReturnOrderNumber?`<p>Order reference <strong>${esc(paymentReturnOrderNumber)}</strong></p>`:''}<p class="subtle">${esc(message)}</p>${['pending','unavailable'].includes(paymentReturnStatus)?'<button class="button outline" onclick="retryPaymentCheck()">Check payment status again</button>':''}<button class="button" onclick="go('track-order')">Track an order</button><button class="text-button" onclick="go('shop')">Continue browsing</button></main>${footer()}`}if(!lastOrder)return `${header()}<main class="section"><h1 class="checkout-title">No recent order request.</h1><button class="button" onclick="go('shop')">Browse fabrics</button></main>${footer()}`;return `${header()}<main class="section confirmation"><span class="eyebrow">Request received</span><h1>Your order request is with us.</h1><p>Reference <strong>${esc(lastOrder.orderNumber)}</strong></p><p class="subtle">This is an unpaid order request. FASTRACK will confirm availability and delivery details before arranging payment.</p><button class="button" onclick="go('shop')">Continue browsing</button></main>${footer()}`}
function ordersPanel(){return `<div class="panel"><div class="panel-head"><h3>Order requests</h3><button class="button outline" onclick="loadOrders()">Refresh</button></div><div id="orders-list"><p class="subtle">Loading order requests…</p></div></div>`}
async function saveOrderStatus(id,status){try{const r=await fetch(`/api/admin/orders/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not update the request.');showToast('Order request updated')}catch(e){showToast(e.message);loadOrders()}}
async function loadOrders(){const el=document.querySelector('#orders-list');if(!el)return;try{const response=await fetch('/api/admin/orders');if(!response.ok)throw new Error('Could not load orders.');const rows=await response.json();if(!rows.length){el.innerHTML='<p class="subtle">There are no orders yet.</p>';return}const statuses=[['pending','Pending confirmation'],['pending_payment','Awaiting payment'],['payment_failed','Payment failed'],['payment_review','Payment review'],['confirmed','Confirmed'],['processing','Processing'],['packed','Packed'],['dispatched','Dispatched'],['delivered','Delivered'],['cancelled','Cancelled']];el.innerHTML=`<div class="table-wrap"><table class="table order-table"><thead><tr><th>Reference</th><th>Customer</th><th>Items</th><th>Subtotal</th><th>Delivery</th><th>Payment</th><th>Status</th><th>Date</th></tr></thead><tbody>${rows.map(order=>`<tr><td><strong>${esc(order.orderNumber)}</strong><br><span class="subtle">${esc(order.deliveryMethod==='pickup'?'Pickup':`${order.city}, ${order.state}`)}</span></td><td>${esc(order.fullName)}<br>${esc(order.phone)}${order.email?`<br>${esc(order.email)}`:''}</td><td>${order.items.map(item=>`${esc(item.productName)} · ${Number(item.quantity).toLocaleString()} ${esc(item.unit)} · ${money(item.lineTotal)}`).join('<br>')}</td><td>${money(order.subtotal)}</td><td>${order.deliveryFee===null?'To confirm':money(order.deliveryFee)}</td><td><strong>${esc(order.paymentStatus||'not configured')}</strong>${order.payment?.reference?`<br><small>Paystack · ${esc(order.payment.reference)}</small>`:''}</td><td><select aria-label="Status for ${esc(order.orderNumber)}" onchange="saveOrderStatus(${order.id},this.value)">${statuses.map(([value,label])=>`<option value="${value}" ${order.status===value?'selected':''}>${label}</option>`).join('')}</select></td><td>${esc(order.createdAt)}</td></tr>${order.instructions?`<tr><td colspan="8" class="subtle">Delivery instructions: ${esc(order.instructions)}</td></tr>`:''}`).join('')}</tbody></table></div><p class="subtle">Paystack orders reserve stock for 30 minutes while payment is pending. Unpaid order requests reserve stock only after staff confirms them; marking an order Delivered deducts reserved stock.</p>`}catch(error){el.textContent=error.message}}
function admin(){page='admin';app.innerHTML='<main class="auth-wrap"><section class="auth-card"><div class="brand">FASTRACK FABRICS<span>ADMINISTRATION</span></div><p class="subtle">Loading secure admin access…</p></section></main>';fetch('/api/admin/session').then(r=>r.json()).then(s=>{adminSession=s;if(s.authenticated){Promise.all([refreshProducts(),refreshSiteContent(),refreshDeliveryZones(true)]).then(drawAdmin).catch(e=>adminError(e.message))}else drawAdminLogin()}).catch(()=>adminError('Could not connect to the local catalog server. Restart it and try again.'))}
function adminError(message){app.innerHTML=`<main class="auth-wrap"><section class="auth-card"><div class="brand">FASTRACK FABRICS<span>ADMINISTRATION</span></div><p>${esc(message)}</p><button class="button" onclick="admin()">Try again</button></section></main>`}
function drawAdminLogin(error=''){const setup=adminSession.needsSetup&&!adminSession.configured;app.innerHTML=`<main class="auth-wrap"><form class="auth-card" onsubmit="${setup?'adminSetup(event)':'adminLogin(event)'}"><div class="brand">FASTRACK FABRICS<span>ADMINISTRATION</span></div><h1>${setup?'Create admin password':'Admin sign in'}</h1><p class="subtle">${setup?'Create the password you will use to manage products and inventory.':'Sign in to manage products and inventory.'}</p>${setup?'<p class="auth-warning">First-time password setup is limited to this computer. Choose at least 14 characters.</p>':''}${error?`<p class="form-error">${esc(error)}</p>`:''}<label>Admin password<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?14:1}" required></label>${setup?'<label>Confirm password<input name="confirmation" type="password" autocomplete="new-password" minlength="14" required></label>':''}<button class="button">${setup?'Set password':'Sign in'}</button><button type="button" class="text-button" onclick="go('home')">Return to storefront</button></form></main>`}async function adminLogin(e){e.preventDefault();const password=new FormData(e.target).get('password');try{const r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})}),data=await r.json();if(!r.ok){drawAdminLogin(data.error);return}adminSession.authenticated=true;await refreshProducts();await refreshSiteContent();drawAdmin()}catch(err){drawAdminLogin(err.message||'Sign in failed.')}}
async function adminSetup(e){e.preventDefault();const fd=new FormData(e.target);try{const r=await fetch('/api/admin/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:fd.get('password'),confirmation:fd.get('confirmation')})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not configure admin access.');adminSession={configured:true,needsSetup:false,authenticated:true,view:'Dashboard'};await refreshProducts();await refreshSiteContent();drawAdmin();showToast('Admin password configured')}catch(err){drawAdminLogin(err.message)}}
async function refreshProducts(){const r=await fetch('/api/products',{cache:'no-store'});if(!r.ok)throw new Error('Catalog could not be loaded.');products=await r.json();return products}
async function refreshSiteContent(){const r=await fetch('/api/site-content',{cache:'no-store'});if(!r.ok)throw new Error('Homepage images could not be loaded.');const data=await r.json();siteContent={heroImage:data.heroImage||siteContent.heroImage,editorialImage:data.editorialImage||siteContent.editorialImage,textureImages:{...siteContent.textureImages,...(data.textureImages||{})}};return siteContent}
async function refreshDeliveryZones(admin=false){const response=await fetch(admin?'/api/admin/delivery-zones':'/api/delivery-zones',{cache:'no-store'});if(!response.ok)throw new Error('Delivery zones could not be loaded.');deliveryZones=await response.json();return deliveryZones}
function statusFor(p){return (p.availableStock??p.stock)<=0?['Out of stock','low']:(p.availableStock??p.stock)<=p.lowStock?['Low stock','low']:['In stock','']}
function productRows(){return products.map(p=>{const [status,cls]=statusFor(p);return `<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${Number(p.availableStock).toLocaleString()} available · ${Number(p.reservedStock).toLocaleString()} reserved ${esc(p.unit.replace(/^per /,''))}</td><td><span class="status ${cls}">${status}</span></td><td><div class="admin-actions"><button class="text-button" onclick="editProduct(${p.id})">Edit</button><button class="text-button" onclick="openStockAdjust(${p.id})">Adjust stock</button></div></td></tr>`}).join('')}
function productsPanel(){return `<div class="panel"><div class="panel-head"><h3>Product catalog · ${products.length}</h3><button class="button" onclick="editProduct()">Add product</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Retail price</th><th>Available</th><th>Status</th><th>Actions</th></tr></thead><tbody>${productRows()}</tbody></table></div></div>`}
function editProduct(id){const p=id?products.find(item=>item.id===id):null;if(id&&!p)return showToast('Product not found.');document.getElementById('product-dialog')?.remove();const image=p?.img?`<img class="image-preview" src="${imageSrc(p.img,480)}" alt="${esc(p.name)} fabric">`:'<div class="image-empty">Select an image to preview it here.</div>';document.body.insertAdjacentHTML('beforeend',`<dialog class="form-dialog" id="product-dialog" aria-labelledby="product-dialog-title"><form class="catalog-form" onsubmit="saveProduct(event)"><div class="panel-head"><h2 id="product-dialog-title">${p?'Edit product':'Add product'}</h2><button class="icon-button" type="button" data-close aria-label="Close product editor">${icon('close')}</button></div><input type="hidden" name="id" value="${p?.id||''}"><input type="hidden" name="img" value="${esc(p?.img||'')}"><div class="form-grid"><label class="form-wide">Product image <span class="subtle">JPEG, PNG or WebP · maximum 6 MB</span><input id="product-image-file" name="imageFile" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="product-image-preview" class="image-preview-wrap form-wide">${image}</div><label>Product name<input name="name" maxlength="160" value="${esc(p?.name||'')}" required></label><label>SKU<input name="sku" maxlength="160" value="${esc(p?.sku||'')}" required></label><label>Category<input name="category" maxlength="160" value="${esc(p?.category||'')}" required></label><label>Fabric type<input name="type" maxlength="160" value="${esc(p?.type||'')}" required></label><label>Colour<input name="color" maxlength="160" value="${esc(p?.color||'')}" required></label><label>Selling unit<input name="unit" maxlength="160" value="${esc(p?.unit||'per yard')}" placeholder="per yard, per metre, per piece" required></label><label>Retail price (₦)<input name="price" type="number" min="0" step="0.01" value="${p?.price??''}" required></label><label>Wholesale price (₦)<input name="wholesalePrice" type="number" min="0" step="0.01" value="${p?.wholesalePrice??''}"></label><label>Cost price (₦)<input name="costPrice" type="number" min="0" step="0.01" value="${p?.costPrice??''}"></label><label>Stock quantity<input name="stock" type="number" min="0" step="0.01" value="${p?.stock??0}" required></label><label>Low-stock threshold<input name="lowStock" type="number" min="0" step="0.01" value="${p?.lowStock??5}" required></label><label class="form-wide">Description<textarea name="description" rows="3" maxlength="4000">${esc(p?.description||'')}</textarea></label></div><p class="form-error" data-error></p><div class="form-actions"><button class="button outline" type="button" data-close>Cancel</button><button class="button" type="submit">${p?'Save changes':'Add product'}</button></div></form></dialog>`);const dialog=document.getElementById('product-dialog');dialog.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.querySelector('#product-image-file').addEventListener('change',event=>previewProductImage(event.target));dialog.addEventListener('close',()=>{if(dialog._previewUrl)URL.revokeObjectURL(dialog._previewUrl);dialog.remove()});dialog.showModal()}
function previewProductImage(input){const file=input.files?.[0],box=document.getElementById('product-image-preview'),dialog=document.getElementById('product-dialog');if(!box||!dialog)return;if(dialog._previewUrl)URL.revokeObjectURL(dialog._previewUrl);if(!file){box.innerHTML='<div class="image-empty">Select an image to preview it here.</div>';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>6*1024*1024){input.value='';box.innerHTML='<div class="image-empty">Choose a JPEG, PNG or WebP image up to 6 MB.</div>';return}dialog._previewUrl=URL.createObjectURL(file);box.innerHTML=`<img class="image-preview" src="${dialog._previewUrl}" alt="Selected product image preview">`}
async function uploadProductImage(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));const r=await fetch('/api/admin/uploads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:file.type,data:btoa(binary)})}),result=await r.json();if(!r.ok)throw new Error(result.error||'Image upload failed.');return result.img}
async function saveProduct(e){e.preventDefault();const form=e.target,error=form.querySelector('[data-error]'),button=form.querySelector('button[type="submit"]'),formData=new FormData(form),id=String(formData.get('id')||'').trim(),data=Object.fromEntries(formData.entries()),file=formData.get('imageFile');delete data.id;delete data.imageFile;error.textContent='';button.disabled=true;button.textContent='Saving…';try{if(file instanceof File&&file.size){if(file.size>6*1024*1024)throw new Error('Choose an image up to 6 MB.');data.img=await uploadProductImage(file)}const endpoint=id?`/api/admin/products/${encodeURIComponent(id)}`:'/api/admin/products',r=await fetch(endpoint,{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await r.json();if(!r.ok)throw new Error(result.error||'Could not save the product.');await refreshProducts();document.getElementById('product-dialog')?.close();drawAdmin();showToast(id?'Product updated':'Product added')}catch(err){error.textContent=err.message||'Could not save the product.';button.disabled=false;button.textContent=id?'Save changes':'Add product'}}
function openStockAdjust(id){const p=products.find(item=>item.id===id);if(!p)return showToast('Product not found.');document.getElementById('stock-dialog')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog class="form-dialog stock-dialog" id="stock-dialog"><form class="catalog-form" onsubmit="saveStockAdjustment(event,${p.id})"><div class="panel-head"><h2>Adjust stock</h2><button class="icon-button" type="button" onclick="document.getElementById('stock-dialog').close()" aria-label="Close stock adjustment">${icon('close')}</button></div><p class="subtle">${esc(p.name)} · ${Number(p.stock).toLocaleString()} ${esc(p.unit.replace(/^per /,''))} currently in stock.</p><label>Stock change <span class="subtle">Use a positive number to add stock or a negative number to remove it.</span><input name="quantity" type="number" step="0.01" required></label><label>Reason<input name="reason" maxlength="200" minlength="3" required></label><p class="form-error" data-error></p><div class="form-actions"><button class="button outline" type="button" onclick="document.getElementById('stock-dialog').close()">Cancel</button><button class="button" type="submit">Save adjustment</button></div></form></dialog>`);document.getElementById('stock-dialog').showModal()}
async function saveStockAdjustment(e,id){e.preventDefault();const form=e.target,error=form.querySelector('[data-error]'),button=form.querySelector('button[type="submit"]'),data=Object.fromEntries(new FormData(form).entries());button.disabled=true;button.textContent='Saving…';error.textContent='';try{const r=await fetch(`/api/admin/products/${id}/adjust`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await r.json();if(!r.ok)throw new Error(result.error||'Could not adjust stock.');await refreshProducts();document.getElementById('stock-dialog')?.close();drawAdmin();showToast('Stock adjustment saved')}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Save adjustment'}}
async function loadMovements(){const el=document.querySelector('#movement-list');if(!el)return;try{const r=await fetch('/api/admin/movements');if(!r.ok)throw new Error('Could not load stock movements.');const rows=await r.json();el.innerHTML=rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Change</th><th>Before</th><th>After</th><th>Reason</th><th>Date</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.name)}<br><span class="subtle">${esc(m.sku)}</span></td><td>${m.quantity>0?'+':''}${Number(m.quantity).toLocaleString()}</td><td>${Number(m.beforeStock).toLocaleString()}</td><td>${Number(m.afterStock).toLocaleString()}</td><td>${esc(m.reason)}</td><td>${esc(m.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">No stock movements have been recorded yet.</p>'}catch(err){el.textContent=err.message}}
function contentPanel(){const fields=[{key:'heroImage',label:'Homepage hero',image:siteContent.heroImage},{key:'editorialImage',label:'Rooted in craft feature',image:siteContent.editorialImage},...categories.map(([label,image])=>({key:`texture:${label}`,label:`${label} card`,image:siteContent.textureImages[label]||image}))];return `<form class="panel site-content-form" onsubmit="saveSiteContent(event)"><div class="panel-head"><div><h3>Homepage images</h3><p class="subtle">Upload the hero, the “Rooted in craft” feature image, and the four “Considered by texture” images.</p></div></div><div class="content-image-grid">${fields.map((field,index)=>`<section class="content-image-card"><h4>${esc(field.label)}</h4><img class="content-image-preview" id="site-preview-${index}" src="${imageSrc(field.image,700)}" alt="${esc(field.label)} preview"><label>Replace image<input type="file" accept="image/jpeg,image/png,image/webp" data-site-image="${esc(field.key)}" data-preview-id="site-preview-${index}" onchange="previewSiteImage(this)"></label></section>`).join('')}</div><p class="form-error" data-error></p><div class="form-actions"><button class="button" type="submit">Save homepage images</button></div></form>`}
function previewSiteImage(input){const file=input.files?.[0],preview=document.getElementById(input.dataset.previewId);if(!preview||!file)return;if(input._previewUrl)URL.revokeObjectURL(input._previewUrl);if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>6*1024*1024){input.value='';showToast('Choose a JPEG, PNG or WebP image up to 6 MB.');return}input._previewUrl=URL.createObjectURL(file);preview.src=input._previewUrl}
async function saveSiteContent(e){e.preventDefault();const form=e.target,error=form.querySelector('[data-error]'),button=form.querySelector('button[type="submit"]'),inputs=[...form.querySelectorAll('[data-site-image]')],data={textureImages:{}};button.disabled=true;button.textContent='Uploading…';error.textContent='';try{let changed=false;for(const input of inputs){const file=input.files?.[0];if(!file)continue;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>6*1024*1024)throw new Error('Choose JPEG, PNG or WebP images up to 6 MB each.');const image=await uploadProductImage(file),key=input.dataset.siteImage;if(key==='heroImage')data.heroImage=image;else if(key==='editorialImage')data.editorialImage=image;else data.textureImages[key.slice('texture:'.length)]=image;changed=true}if(!changed)throw new Error('Choose at least one image to replace.');const r=await fetch('/api/admin/site-content',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await r.json();if(!r.ok)throw new Error(result.error||'Homepage images could not be saved.');siteContent={heroImage:result.heroImage||siteContent.heroImage,editorialImage:result.editorialImage||siteContent.editorialImage,textureImages:{...siteContent.textureImages,...(result.textureImages||{})}};for(const input of inputs)if(input._previewUrl)URL.revokeObjectURL(input._previewUrl);drawAdmin();showToast('Homepage images updated')}catch(err){error.textContent=err.message||'Homepage images could not be saved.';button.disabled=false;button.textContent='Save homepage images'}}
function adminRequestPanel(type){const titles={wholesale:'Wholesale applications',samples:'Fabric sample requests',quotes:'Quote requests'};return `<div class="panel"><div class="panel-head"><div><h3>${titles[type]}</h3><p class="subtle">Customer requests are stored in the local database.</p></div><button class="button outline" onclick="loadAdminRequests('${type}')">Refresh</button></div><div id="request-list"><p class="subtle">Loading requests…</p></div></div>`}
function loadAdminRequests(type){const el=document.querySelector('#request-list');if(!el)return;fetch(`/api/admin/${type}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not load requests.');return data}).then(rows=>{if(!el.isConnected)return;if(!rows.length){el.innerHTML='<p class="subtle">No requests have been received yet.</p>';return}const options={wholesale:['new','contacted','approved','rejected'],samples:['new','contacted','processing','sent','completed','cancelled'],quotes:['draft','sent','accepted','rejected','expired','converted']}[type],select=(row)=>`<select aria-label="Request status" ${type==='quotes'?'name="status"':`onchange="updateAdminRequest('${type}',${row.id},this.value)"`}>${options.map(status=>`<option value="${status}" ${row.status===status?'selected':''}>${status[0].toUpperCase()+status.slice(1)}</option>`).join('')}</select>`;if(type==='wholesale'){el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Applicant</th><th>Business</th><th>Contact</th><th>Business details</th><th>Monthly purchase</th><th>Status</th><th>Date</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.fullName)}</td><td>${esc(row.businessName)}<br><span class="subtle">${esc(row.businessType)}</span></td><td>${esc(row.phone)}<br>${esc(row.email)}</td><td>${esc(row.businessAddress)}<br>${esc(row.state)}${row.onlinePresence?`<br>${esc(row.onlinePresence)}`:''}</td><td>${esc(row.monthlyPurchase||'Not supplied')}</td><td>${select(row)}</td><td>${esc(row.createdAt)}</td></tr>${row.additionalInfo?`<tr><td colspan="7" class="subtle">Additional information: ${esc(row.additionalInfo)}</td></tr>`:''}`).join('')}</tbody></table></div>`}else if(type==='samples'){el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Fabric</th><th>Colour and quantity</th><th>Delivery location</th><th>Contact</th><th>Status</th><th>Date</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.fullName)}</td><td>${esc(row.productName)}<br><span class="subtle">${esc(row.sku)}</span></td><td>${esc(row.preferredColour)} · ${Number(row.quantity).toLocaleString()}</td><td>${esc(row.deliveryLocation)}</td><td>${esc(row.phone)}${row.email?`<br>${esc(row.email)}`:''}</td><td>${select(row)}</td><td>${esc(row.createdAt)}</td></tr>${row.message?`<tr><td colspan="7" class="subtle">Message: ${esc(row.message)}</td></tr>`:''}`).join('')}</tbody></table></div>`}else{el.innerHTML=`<div class="table-wrap"><table class="table quote-table"><thead><tr><th>Reference</th><th>Customer</th><th>Fabric and quantity</th><th>Delivery and deadline</th><th>Requested details</th><th>Prepare response</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.quoteNumber)}</strong><br>${esc(row.createdAt)}</td><td>${esc(row.fullName)}<br>${esc(row.phone)}${row.email?`<br>${esc(row.email)}`:''}</td><td>${esc(row.productName)}<br><span class="subtle">${esc(row.sku)} · ${esc(row.desiredColour)} · ${Number(row.quantity).toLocaleString()}</span></td><td>${esc(row.deliveryLocation)}<br><span class="subtle">${esc(row.deadline||'No deadline')}</span></td><td>${esc(row.message||'No additional details')}</td><td><form class="quote-admin-form" onsubmit="saveAdminRequest(event,'quotes',${row.id})">${select(row)}<label>Quotation total (₦)<input name="quotedAmount" type="number" min="0" step="0.01" value="${row.quotedAmount??''}"></label><label>Response<input name="response" maxlength="2000" value="${esc(row.response)}"></label><button class="button outline" type="submit">Save response</button></form></td></tr>`).join('')}</tbody></table></div>`}}).catch(error=>{if(el.isConnected)el.textContent=error.message})}
async function updateAdminRequest(type,id,status){try{const response=await fetch(`/api/admin/${type}/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not update request.');showToast('Request status updated')}catch(error){showToast(error.message);loadAdminRequests(type)}}
async function saveAdminRequest(event,type,id){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form).entries());try{const response=await fetch(`/api/admin/${type}/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save quotation.');showToast('Quotation updated');loadAdminRequests(type)}catch(error){showToast(error.message)}}
function deliveryZoneRow(zone={}){return `<div class="delivery-zone-row"><label>State<input data-zone-field="state" maxlength="80" value="${esc(zone.state||'')}" required></label><label>City or area <span class="subtle">Leave blank for the whole state</span><input data-zone-field="city" maxlength="120" value="${esc(zone.city||'')}"></label><label>Fee (₦)<input data-zone-field="fee" type="number" min="0" step="0.01" value="${zone.fee??''}" required></label><label>Estimated delivery<input data-zone-field="estimate" maxlength="120" value="${esc(zone.estimate||'')}" placeholder="1–3 business days" required></label><label class="zone-active"><input data-zone-field="active" type="checkbox" ${zone.active===false||zone.active===0?'':'checked'}> Active</label><button class="text-button" type="button" onclick="this.closest('.delivery-zone-row').remove()">Remove row</button></div>`}
function deliverySettingsPanel(){return `<form class="panel delivery-settings" onsubmit="saveDeliveryZones(event)"><div class="panel-head"><div><h3>Nigerian delivery zones</h3><p class="subtle">Set a fee and estimate for each state or city. A blank city applies to the whole state; city-specific zones take priority.</p></div></div><div id="delivery-zone-list">${deliveryZones.map(deliveryZoneRow).join('')||'<p class="subtle">No zones configured. Delivery charges will need to be confirmed manually.</p>'}</div><div class="new-zone-grid"><label>State<input name="newState" maxlength="80" placeholder="Lagos"></label><label>City or area <span class="subtle">Optional</span><input name="newCity" maxlength="120" placeholder="Ikeja"></label><label>Fee (₦)<input name="newFee" type="number" min="0" step="0.01"></label><label>Estimated delivery<input name="newEstimate" maxlength="120" placeholder="1–3 business days"></label><button class="button outline" type="button" onclick="addDeliveryZoneRow()">Add zone</button></div><p class="form-error" data-error></p><div class="form-actions"><button class="button" type="submit">Save delivery zones</button></div></form>`}
function addDeliveryZoneRow(){const form=document.querySelector('.delivery-settings'),state=form?.elements.newState.value.trim(),city=form?.elements.newCity.value.trim(),fee=form?.elements.newFee.value,estimate=form?.elements.newEstimate.value.trim(),list=document.querySelector('#delivery-zone-list');if(!state||fee===''||!estimate){showToast('Enter the state, fee and delivery estimate first.');return}if(!list.querySelector('.delivery-zone-row'))list.innerHTML='';list.insertAdjacentHTML('beforeend',deliveryZoneRow({state,city,fee:Number(fee),estimate,active:true}));form.reset()}
async function saveDeliveryZones(event){event.preventDefault();const form=event.currentTarget,error=form.querySelector('[data-error]'),button=form.querySelector('button[type="submit"]'),zones=[...form.querySelectorAll('.delivery-zone-row')].map(row=>({state:row.querySelector('[data-zone-field="state"]').value,city:row.querySelector('[data-zone-field="city"]').value,fee:row.querySelector('[data-zone-field="fee"]').value,estimate:row.querySelector('[data-zone-field="estimate"]').value,active:row.querySelector('[data-zone-field="active"]').checked}));error.textContent='';button.disabled=true;button.textContent='Saving…';try{const response=await fetch('/api/admin/delivery-zones',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({zones})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save delivery zones.');deliveryZones=result;drawAdmin();showToast('Delivery zones saved')}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Save delivery zones'}}
function adminSection(n){adminSession.view=n;if(n==='Settings'){refreshDeliveryZones(true).then(drawAdmin).catch(err=>showToast(err.message))}else drawAdmin()}
function adminDashboardMarkup(low,out,inStock){const watch=products.filter(p=>(p.availableStock??p.stock)<=p.lowStock).slice(0,5);return `<section class="dashboard-intro"><div><span class="eyebrow">Store overview</span><h2>Keep the fabric business moving.</h2><p>Product availability and customer order requests, in one place.</p></div><button class="button outline" type="button" onclick="adminSection('Orders')">View all order requests ${icon('arrow',15)}</button></section><section class="metric-grid" aria-label="Catalog summary">${[['Products',products.length,'Active catalog items'],['Healthy stock',inStock,'Products above their threshold'],['Low stock',low,'Products to replenish'],['Out of stock',out,'Unavailable catalog items']].map(([label,value,caption],index)=>`<article class="metric metric-${index}"><span class="metric-label">${label}</span><strong>${value}</strong><span class="metric-caption">${caption}</span></article>`).join('')}</section><section class="dashboard-grid"><div class="panel dashboard-orders-panel"><div class="panel-head"><div><span class="eyebrow">Fulfilment</span><h3>Recent order requests</h3></div><button class="text-button" type="button" onclick="adminSection('Orders')">Open orders ${icon('arrow',14)}</button></div><div id="dashboard-orders"><p class="subtle">Loading recent requests…</p></div></div><aside class="panel inventory-watch"><div class="panel-head"><div><span class="eyebrow">Stock health</span><h3>Needs attention</h3></div><button class="text-button" type="button" onclick="adminSection('Inventory')">Inventory ${icon('arrow',14)}</button></div>${watch.length?`<div class="inventory-watch-list">${watch.map(p=>{const available=Number(p.availableStock??p.stock),label=available<=0?'Out of stock':'Low stock',status=available<=0?'out':'low';return `<div class="inventory-watch-row"><img src="${imageSrc(p.img,100)}" alt=""><span class="inventory-watch-name"><strong>${esc(p.name)}</strong><small>${available.toLocaleString()} ${esc((p.unit||'units').replace(/^per /,''))} available</small></span><span class="admin-status admin-status--${status}">${label}</span></div>`}).join('')}</div>`:'<div class="admin-empty">Inventory is within its configured thresholds.</div>'}</aside></section>`}
async function loadDashboardOrders(){const el=document.querySelector('#dashboard-orders');if(!el)return;try{const response=await fetch('/api/admin/orders');if(!response.ok)throw new Error('Could not load recent order requests.');const rows=await response.json();if(!rows.length){el.innerHTML='<div class="admin-empty">Customer order requests will appear here when they are submitted.</div>';return}const recent=rows.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,5);el.innerHTML=`<div class="table-wrap"><table class="table dashboard-orders-table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Request total</th><th>Status</th></tr></thead><tbody>${recent.map(order=>{const status=String(order.status||'pending').toLowerCase(),statusClass=status.replace(/[^a-z-]/g,''),itemCount=(order.items||[]).reduce((sum,item)=>sum+Number(item.quantity||0),0);return `<tr><td><strong>${esc(order.orderNumber)}</strong><small>${esc(order.createdAt||'')}</small></td><td>${esc(order.fullName)}</td><td>${itemCount.toLocaleString()} ${itemCount===1?'item':'items'}</td><td>${money(order.subtotal)}</td><td><span class="admin-status admin-status--${statusClass}">${esc(status.replace(/-/g,' '))}</span></td></tr>`}).join('')}</tbody></table></div>`}catch(error){el.innerHTML=`<div class="admin-empty">${esc(error.message||'Recent requests are unavailable.')}</div>`}}
function drawAdmin(){adminSession.view=adminSession.view||'Dashboard';const low=products.filter(p=>(p.availableStock??p.stock)>0&&(p.availableStock??p.stock)<=p.lowStock).length,out=products.filter(p=>(p.availableStock??p.stock)<=0).length,inStock=products.length-low-out;const nav=[['Dashboard','chart'],['Products','box'],['Inventory','box'],['Orders','bag'],['Customers','users'],['Wholesale','users'],['Sample requests','box'],['Quote requests','box'],['Suppliers','box'],['Promotions','box'],['Reports','chart'],['Website content','box'],['Settings','settings']];let content='';if(adminSession.view==='Dashboard')content=adminDashboardMarkup(low,out,inStock);else if(adminSession.view==='Products')content=productsPanel();else if(adminSession.view==='Inventory')content=`<div class="panel"><div class="panel-head"><h3>Stock movement history</h3><button class="button outline" onclick="loadMovements()">Refresh</button></div><div id="movement-list"><p class="subtle">Loading recent stock movements…</p></div></div>${productsPanel()}`;else if(adminSession.view==='Orders')content=ordersPanel();else if(adminSession.view==='Website content')content=contentPanel();else if(adminSession.view==='Wholesale')content=adminRequestPanel('wholesale');else if(adminSession.view==='Sample requests')content=adminRequestPanel('samples');else if(adminSession.view==='Quote requests')content=adminRequestPanel('quotes');else if(adminSession.view==='Settings')content=deliverySettingsPanel();else content=`<div class="panel"><h3>${esc(adminSession.view)}</h3><p class="subtle">This workflow is not part of the current catalog, inventory and order-request milestone.</p></div>`;app.innerHTML=`<div class="admin"><aside class="sidebar"><div class="side-brand"><div class="admin-brand-mark">F</div><div class="admin-brand-copy"><strong>FASTRACK</strong><span>FABRICS · STUDIO</span></div></div>${nav.map(([n,i])=>`<button class="side-link ${adminSession.view===n?'active':''}" onclick="adminSection('${n}')">${icon(i,16)}${n}</button>`).join('')}</aside><main class="admin-main"><div class="admin-head"><div><span class="eyebrow">FASTRACK FABRICS · BUSINESS</span><h1>${esc(adminSession.view)}</h1></div><div class="admin-actions"><span class="subtle">Signed in</span><button class="button outline" onclick="go('home')">View storefront</button><button class="text-button" onclick="adminLogout()">Sign out</button></div></div>${content}<div class="subtle admin-note">Catalog, customer requests and stock movements are saved in the local database. ${paymentsEnabled?'Paystack online payments are active.':'Paystack online payments are not configured.'}</div></main></div>`;if(adminSession.view==='Inventory')loadMovements();if(adminSession.view==='Dashboard')loadDashboardOrders();if(adminSession.view==='Orders')loadOrders();if(adminSession.view==='Wholesale')loadAdminRequests('wholesale');if(adminSession.view==='Sample requests')loadAdminRequests('samples');if(adminSession.view==='Quote requests')loadAdminRequests('quotes')}
async function adminLogout(){await fetch('/api/admin/logout',{method:'POST'});adminSession.authenticated=false;drawAdminLogin()}
